/**
 * A date range *field* with two segmented entries and a calendar popup (`design/components/date-range-picker.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/date-range-picker.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'
import { Portal } from 'solid-js/web'

import * as zag from '@zag-js/popover'
import { normalizeProps } from '@zag-js/solid'

import {
  Each,
  Icon,
  agentDateRange,
  agentMember,
  anchorProps,
  calendarDateOf,
  claimSlot,
  createCell,
  createDerived,
  dateFieldDraft,
  dateFieldValue,
  dateOutOfBounds,
  elementRef,
  eraseSegment,
  fieldSegments,
  itemOf,
  mergeParts,
  scope,
  stepSegment,
  syncTriggerAnchor,
  typeIntoSegment,
  useDirection,
  useMachine,
  useMediaQuery,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/controls/date-range-picker.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import triggerAnchor from '@polymorph/recipes/overlays/trigger-anchor.module.css'
import Button from './Button'
import DateRangePickerRangeCalendar from './DateRangePickerRangeCalendar'
import type { CalendarDate, CalendarMessages } from './Calendar'

export interface DateRange {
  start: CalendarDate
  end: CalendarDate
}

export type DateRangePickerMessages = CalendarMessages & {
  showCalendar: string
  clear: string
  chooseRange: string
}

export interface DateRangePickerProps {
  'aria-describedby'?: string
  /**
   * Set by FormField. Set it directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  /**
   * DatePicker's clear button: reports `onChange(null)` and resets both groups to placeholders.
   */
  clearable?: boolean
  /**
   * Opens on mount, for galleries and tests. Screens let the user open it.
   */
  defaultOpen?: boolean
  defaultValue?: DateRange | null
  disabled?: boolean
  endName?: string
  firstDayOfWeek?: 0 | 1 | 2 | 3 | 4 | 5 | 6
  id?: string
  invalid?: boolean
  isDateUnavailable?: (date: CalendarDate) => boolean
  /**
   * Also orders the segments and picks the separators.
   */
  locale?: string
  maxValue?: CalendarDate
  /**
   * Defaults to generic English. Localized hosts pass strings from their catalog.
   */
  messages?: DateRangePickerMessages
  /**
   * react-aria's validation, forwarded. A typed date outside the bounds marks the field invalid.
   * React Aria marks a reversed pair (end before start) invalid on both halves.
   */
  minValue?: CalendarDate
  onChange?: (value: DateRange | null) => void
  /**
   * Same as DatePicker (`date-picker.md`, the conventions' sheet presentation). `'auto'` shows
   * the popup as a sheet below `30rem`, with RangeCalendar unchanged inside it. `'popover'`
   * keeps the popover at every width. The anchored-range keyboard model, the two-stage Escape
   * and the focus hand-off work the same after re-anchoring.
   */
  presentation?: 'auto' | 'popover'
  size?: 'sm' | 'md' | 'lg'
  /**
   * Two hidden inputs serialize ISO-8601, as DatePicker does, once per end, because one `name`
   * cannot carry two values.
   */
  startName?: string
  /**
   * Both ends or `null`. A half-entered range is never reported. `onChange` fires when the
   * second end is committed, and clearing reports `null`. Uses `CalendarDate`, never `Date`
   * (Calendar's law).
   */
  value?: DateRange | null
}

/** A date range *field* with two segmented entries and a calendar popup. */
export default function DateRangePicker(given: DateRangePickerProps): JSX.Element {
  const props = mergeProps(
    {
      clearable: false,
      size: 'md',
      disabled: false,
      invalid: false,
      presentation: 'auto',
    } as Defaults<
      DateRangePickerProps,
      'clearable' | 'size' | 'disabled' | 'invalid' | 'presentation'
    >,
    claimSlot(given, 'group'),
  )
  return scope(() => {
    const uid = createUniqueId()
    const browserLanguage = createCell(undefined as string | undefined)
    const startDraft = createCell(
      dateFieldDraft((props.value !== undefined ? props.value : props.defaultValue)?.start, {
        locale: props.locale ?? browserLanguage.value ?? 'en-US',
        parts: ['year', 'month', 'day'] as const,
      }),
    )
    const endDraft = createCell(
      dateFieldDraft((props.value !== undefined ? props.value : props.defaultValue)?.end, {
        locale: props.locale ?? browserLanguage.value ?? 'en-US',
        parts: ['year', 'month', 'day'] as const,
      }),
    )
    const typed = createCell('')
    const reported = createCell(
      ((given) =>
        given === null || given === undefined
          ? ''
          : `${given.start.toString()}/${given.end.toString()}`)(
        props.value !== undefined ? props.value : props.defaultValue,
      ),
    )
    const anchored = createCell(false)
    const anchor = elementRef<HTMLElement>()
    const field = elementRef<HTMLElement>()
    const panel = elementRef<HTMLElement>()
    const scrim = elementRef<HTMLElement>()
    const sheetPanel = elementRef<HTMLElement>()
    const phone = useMediaQuery('phone')
    const say = createDerived(
      () =>
        props.messages ?? {
          previousMonth: 'Previous month',
          nextMonth: 'Next month',
          showCalendar: 'Show calendar',
          clear: 'Clear',
          chooseRange: 'Choose a date range',
        },
    )
    const language = createDerived(() => props.locale ?? browserLanguage.value ?? 'en-US')
    const sheeting = createDerived(() => props.presentation === 'auto' && phone())
    const fieldOptions = createDerived(() => ({
      locale: language.value,
      parts: ['year', 'month', 'day'] as const,
    }))
    const startSegments = createDerived(() => fieldSegments(startDraft.value, fieldOptions.value))
    const endSegments = createDerived(() => fieldSegments(endDraft.value, fieldOptions.value))
    const rangeOf = createDerived(
      () =>
        (
          start: ReturnType<typeof dateFieldDraft>,
          end: ReturnType<typeof dateFieldDraft>,
        ): DateRange | null => {
          const from = dateFieldValue(start, fieldOptions.value)
          const to = dateFieldValue(end, fieldOptions.value)
          return from === null || to === null
            ? null
            : { start: calendarDateOf(from), end: calendarDateOf(to) }
        },
    )
    const range = createDerived(() => rangeOf.value(startDraft.value, endDraft.value))
    const bounds = createDerived(() => ({
      min: props.minValue,
      max: props.maxValue,
      unavailable: props.isDateUnavailable,
    }))
    const fieldInvalid = createDerived(
      () =>
        props.invalid ||
        dateOutOfBounds(dateFieldValue(startDraft.value, fieldOptions.value), bounds.value) ||
        dateOutOfBounds(dateFieldValue(endDraft.value, fieldOptions.value), bounds.value) ||
        (range.value !== null && range.value.end.compare(range.value.start) < 0),
    )
    const showClear = createDerived(
      () => props.clearable && range.value !== null && !props.disabled,
    )
    const report = createDerived(
      () =>
        (
          start: ReturnType<typeof dateFieldDraft>,
          end: ReturnType<typeof dateFieldDraft>,
        ): void => {
          startDraft.value = start
          endDraft.value = end
          const after = rangeOf.value(start, end)
          const text = after === null ? '' : `${after.start.toString()}/${after.end.toString()}`
          if (text !== reported.value) {
            reported.value = text
            props.onChange?.(after)
          }
        },
    )
    const startCommit = createDerived(
      () =>
        (next: ReturnType<typeof dateFieldDraft>): void =>
          report.value(next, endDraft.value),
    )
    const endCommit = createDerived(
      () =>
        (next: ReturnType<typeof dateFieldDraft>): void =>
          report.value(startDraft.value, next),
    )
    const clear = createDerived(() => (): void => {
      report.value({}, {})
      field.value?.querySelector<HTMLElement>('[data-segment]')?.focus()
    })
    const segmentName = createDerived(() => (type: string): string => {
      try {
        return new Intl.DisplayNames(language.value, { type: 'dateTimeField' }).of(type) ?? type
      } catch {
        return type
      }
    })
    const moveSegment = createDerived(() => (from: EventTarget | null, step: number): void => {
      if (!(from instanceof HTMLElement)) return
      const all = [
        ...(from.closest('[role="group"]')?.querySelectorAll<HTMLElement>('[data-segment]') ?? []),
      ]
      all[all.indexOf(from) + step]?.focus()
    })
    const startInput = createDerived(
      () =>
        (event: Event, segment: ReturnType<typeof fieldSegments>[number]): void => {
          event.preventDefault()
          if (segment.type === 'literal' || !!props.disabled) return
          const data = (event as InputEvent).data ?? ''
          for (const key of data) {
            const next = typeIntoSegment(
              startDraft.value,
              segment.type,
              typed.value,
              key,
              fieldOptions.value,
            )
            typed.value = next.typed
            startCommit.value(next.draft)
            if (next.advance) {
              moveSegment.value(event.currentTarget, 1)
              break
            }
          }
        },
    )
    const endInput = createDerived(
      () =>
        (event: Event, segment: ReturnType<typeof fieldSegments>[number]): void => {
          event.preventDefault()
          if (segment.type === 'literal' || !!props.disabled) return
          const data = (event as InputEvent).data ?? ''
          for (const key of data) {
            const next = typeIntoSegment(
              endDraft.value,
              segment.type,
              typed.value,
              key,
              fieldOptions.value,
            )
            typed.value = next.typed
            endCommit.value(next.draft)
            if (next.advance) {
              moveSegment.value(event.currentTarget, 1)
              break
            }
          }
        },
    )
    const documentDirection = useDirection()
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          defaultOpen: props.defaultOpen,
          modal: sheeting.value,
          positioning: { placement: 'bottom-end' as const, offset: { mainAxis: 2 } },
          ids: props.id === undefined ? undefined : { anchor: props.id },
          initialFocusEl: () =>
            (sheetPanel.value ?? panel.value)?.querySelector<HTMLElement>('[tabindex="0"]') ?? null,
          onEscapeKeyDown: (details) => {
            void (anchored.value && details.preventDefault())
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const choose = createDerived(() => (next: DateRange): void => {
      report.value(
        dateFieldDraft(next.start, fieldOptions.value),
        dateFieldDraft(next.end, fieldOptions.value),
      )
      api.value.setOpen(false)
    })
    const startKeys = createDerived(
      () =>
        (event: KeyboardEvent, segment: ReturnType<typeof fieldSegments>[number]): void => {
          if (segment.type === 'literal') return
          if (event.altKey && event.key === 'ArrowDown') {
            event.preventDefault()
            if (!props.disabled) api.value.setOpen(true)
            return
          }
          if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
            event.preventDefault()
            typed.value = ''
            moveSegment.value(
              event.currentTarget,
              (event.key === 'ArrowRight') ===
                (getComputedStyle(event.currentTarget as HTMLElement).direction !== 'rtl')
                ? 1
                : -1,
            )
            return
          }
          if (event.ctrlKey || event.metaKey || event.key === 'Tab') return
          const editable = !props.disabled
          if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
            event.preventDefault()
            typed.value = ''
            if (editable)
              startCommit.value(
                stepSegment(
                  startDraft.value,
                  segment.type,
                  event.key === 'ArrowUp' ? 1 : -1,
                  fieldOptions.value,
                ),
              )
            return
          }
          if (event.key === 'Backspace' || event.key === 'Delete') {
            event.preventDefault()
            typed.value = ''
            if (!editable) return
            if (startDraft.value[segment.type] === undefined)
              moveSegment.value(event.currentTarget, -1)
            else startCommit.value(eraseSegment(startDraft.value, segment.type, fieldOptions.value))
            return
          }
          if (event.key.length !== 1) return
          event.preventDefault()
          if (editable)
            ((key: string): void => {
              const next = typeIntoSegment(
                startDraft.value,
                segment.type,
                typed.value,
                key,
                fieldOptions.value,
              )
              typed.value = next.typed
              startCommit.value(next.draft)
              if (next.advance) moveSegment.value(event.currentTarget, 1)
            })(event.key)
        },
    )
    const endKeys = createDerived(
      () =>
        (event: KeyboardEvent, segment: ReturnType<typeof fieldSegments>[number]): void => {
          if (segment.type === 'literal') return
          if (event.altKey && event.key === 'ArrowDown') {
            event.preventDefault()
            if (!props.disabled) api.value.setOpen(true)
            return
          }
          if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
            event.preventDefault()
            typed.value = ''
            moveSegment.value(
              event.currentTarget,
              (event.key === 'ArrowRight') ===
                (getComputedStyle(event.currentTarget as HTMLElement).direction !== 'rtl')
                ? 1
                : -1,
            )
            return
          }
          if (event.ctrlKey || event.metaKey || event.key === 'Tab') return
          const editable = !props.disabled
          if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
            event.preventDefault()
            typed.value = ''
            if (editable)
              endCommit.value(
                stepSegment(
                  endDraft.value,
                  segment.type,
                  event.key === 'ArrowUp' ? 1 : -1,
                  fieldOptions.value,
                ),
              )
            return
          }
          if (event.key === 'Backspace' || event.key === 'Delete') {
            event.preventDefault()
            typed.value = ''
            if (!editable) return
            if (endDraft.value[segment.type] === undefined)
              moveSegment.value(event.currentTarget, -1)
            else endCommit.value(eraseSegment(endDraft.value, segment.type, fieldOptions.value))
            return
          }
          if (event.key.length !== 1) return
          event.preventDefault()
          if (editable)
            ((key: string): void => {
              const next = typeIntoSegment(
                endDraft.value,
                segment.type,
                typed.value,
                key,
                fieldOptions.value,
              )
              typed.value = next.typed
              endCommit.value(next.draft)
              if (next.advance) moveSegment.value(event.currentTarget, 1)
            })(event.key)
        },
    )
    const present = usePresence(
      () => api.value.open && !sheeting.value,
      () => panel.value,
    )
    const sheetPresent = usePresence(
      () => api.value.open && sheeting.value,
      () => sheetPanel.value,
      'sheet.panel',
      { sheetSide: 'bottom' },
    )
    const scrimPresent = usePresence(
      () => api.value.open && sheeting.value,
      () => scrim.value,
      'dialog.scrim',
    )
    const effect1 = () => {
      browserLanguage.value = globalThis.navigator?.language
    }
    onMount(effect1)
    const effect2 = () => {
      syncTriggerAnchor(anchor.value, api.value.getTriggerProps(), api.value.open)
    }
    watchEffect(
      createMemo(() => api.value.open),
      effect2,
      true,
    )
    const effect3 = () => {
      void (
        props.value !== undefined &&
        (props.value !== null || range.value !== null) &&
        ((startDraft.value = dateFieldDraft(props.value?.start, fieldOptions.value)),
        (endDraft.value = dateFieldDraft(props.value?.end, fieldOptions.value)),
        (reported.value = ((given) =>
          given === null || given === undefined
            ? ''
            : `${given.start.toString()}/${given.end.toString()}`)(props.value)))
      )
    }
    watchEffect(
      createMemo(() => props.value),
      effect3,
      false,
    )
    let release4: (() => void) | undefined
    const effect4 = () => {
      release4?.()
      const ran = agentMember({
        member: 'DateRangePicker',
        element: () => field.value,
        state: () => ({
          value:
            range.value === null
              ? ''
              : `${range.value.start.toString()}/${range.value.end.toString()}`,
          open: api.value.open,
          disabled: props.disabled,
          invalid: fieldInvalid.value,
        }),
        actions: {
          set: {
            argument: 'text',
            run: (value) =>
              ((next) =>
                report.value(
                  dateFieldDraft(next.start, fieldOptions.value),
                  dateFieldDraft(next.end, fieldOptions.value),
                ))(agentDateRange(value, bounds.value)),
          },
          clear: () => report.value({}, {}),
          open: () => api.value.setOpen(true),
          close: () => api.value.setOpen(false),
        },
        withholds: () => [field.value, sheetPanel.value ?? panel.value],
      })
      release4 = () => {
        ran()
      }
    }
    onMount(effect4)
    onCleanup(() => release4?.())
    return (
      <>
        {/* field */}
        <div
          {...mergeParts(api.value.getAnchorProps(), {
            class: styles.field,
            role: 'group',
            'aria-label': props['aria-label'],
            'aria-labelledby': props['aria-labelledby'],
            'aria-describedby': props['aria-describedby'],
            'aria-disabled': props.disabled ? 'true' : undefined,
            'data-size': props.size,
            'data-disabled': props.disabled ? '' : undefined,
            'data-invalid': fieldInvalid.value ? '' : undefined,
            'data-state': api.value.open ? 'open' : 'closed',
            'data-member': 'date-range-picker',
          })}
          ref={field.attach}
        >
          {/* segments */}
          <div class={styles.segments} data-size={props.size}>
            <Each
              of={startSegments.value}
              by={(segment, at) => `start-${segment.type}-${at}`}
              renew
            >
              {(segment) => (
                <>
                  {segment.type === 'literal' ? (
                    <span class={styles.separator} aria-hidden="true">
                      {segment.text}
                    </span>
                  ) : (
                    <div
                      class={styles.segment}
                      role="spinbutton"
                      id={`${uid}-start-${segment.type}`}
                      aria-label={`${'Start date'}, ${segmentName.value(segment.type)}`}
                      aria-labelledby={
                        props['aria-labelledby']
                          ? `${props['aria-labelledby']} ${uid}-start-${segment.type}`
                          : undefined
                      }
                      aria-describedby={props['aria-describedby']}
                      aria-valuenow={segment.placeholder ? undefined : segment.value}
                      aria-valuemin={segment.min}
                      aria-valuemax={segment.max}
                      aria-valuetext={segment.placeholder ? 'Empty' : segment.text}
                      aria-required={props['aria-required'] ? 'true' : undefined}
                      aria-disabled={props.disabled ? 'true' : undefined}
                      aria-invalid={fieldInvalid.value ? 'true' : undefined}
                      contenteditable={!props.disabled ? 'true' : undefined}
                      inputmode={segment.type === 'dayPeriod' ? undefined : 'numeric'}
                      spellcheck="false"
                      tabindex={props.disabled ? undefined : '0'}
                      data-segment={segment.type}
                      data-placeholder={segment.placeholder ? '' : undefined}
                      data-disabled={props.disabled ? '' : undefined}
                      onfocus={() => (typed.value = '')}
                      onkeydown={($event: KeyboardEvent) =>
                        startKeys.value($event, itemOf(segment))
                      }
                      onbeforeinput={($event: InputEvent) =>
                        startInput.value($event, itemOf(segment))
                      }
                    >
                      {segment.text}
                    </div>
                  )}
                </>
              )}
            </Each>
          </div>
          {/* dash */}
          <span class={styles.dash} aria-hidden="true">
            –
          </span>
          {/* segments */}
          <div class={styles.segments} data-size={props.size}>
            <Each of={endSegments.value} by={(segment, at) => `end-${segment.type}-${at}`} renew>
              {(segment) => (
                <>
                  {segment.type === 'literal' ? (
                    <span class={styles.separator} aria-hidden="true">
                      {segment.text}
                    </span>
                  ) : (
                    <div
                      class={styles.segment}
                      role="spinbutton"
                      id={`${uid}-end-${segment.type}`}
                      aria-label={`${'End date'}, ${segmentName.value(segment.type)}`}
                      aria-labelledby={
                        props['aria-labelledby']
                          ? `${props['aria-labelledby']} ${uid}-end-${segment.type}`
                          : undefined
                      }
                      aria-describedby={props['aria-describedby']}
                      aria-valuenow={segment.placeholder ? undefined : segment.value}
                      aria-valuemin={segment.min}
                      aria-valuemax={segment.max}
                      aria-valuetext={segment.placeholder ? 'Empty' : segment.text}
                      aria-required={props['aria-required'] ? 'true' : undefined}
                      aria-disabled={props.disabled ? 'true' : undefined}
                      aria-invalid={fieldInvalid.value ? 'true' : undefined}
                      contenteditable={!props.disabled ? 'true' : undefined}
                      inputmode={segment.type === 'dayPeriod' ? undefined : 'numeric'}
                      spellcheck="false"
                      tabindex={props.disabled ? undefined : '0'}
                      data-segment={segment.type}
                      data-placeholder={segment.placeholder ? '' : undefined}
                      data-disabled={props.disabled ? '' : undefined}
                      onfocus={() => (typed.value = '')}
                      onkeydown={($event: KeyboardEvent) => endKeys.value($event, itemOf(segment))}
                      onbeforeinput={($event: InputEvent) =>
                        endInput.value($event, itemOf(segment))
                      }
                    >
                      {segment.text}
                    </div>
                  )}
                </>
              )}
            </Each>
          </div>
          <span class={styles.spacer} />
          {props.startName !== undefined ? (
            <input
              type="hidden"
              name={props.startName}
              value={range.value?.start.toString() ?? ''}
              disabled={props.disabled ? true : undefined}
            />
          ) : null}
          {props.endName !== undefined ? (
            <input
              type="hidden"
              name={props.endName}
              value={range.value?.end.toString() ?? ''}
              disabled={props.disabled ? true : undefined}
            />
          ) : null}
          {showClear.value ? (
            <button
              class={styles.clear}
              type="button"
              aria-label={say.value.clear}
              onclick={() => clear.value()}
            >
              <Icon name="clear" size={props.size} />
            </button>
          ) : null}
          {/* trigger */}
          <span
            {...mergeParts(anchorProps(api.value.getTriggerProps()), {
              class: triggerAnchor.anchor,
            })}
            ref={anchor.attach}
          >
            <Button
              variant="ghost"
              tone="neutral"
              size={props.size}
              iconOnly={true}
              icon="calendar"
              label={say.value.showCalendar}
              disabled={props.disabled}
            />
          </span>
        </div>
        <Portal>
          {present() ? (
            <div {...mergeParts(api.value.getPositionerProps())}>
              {/* panel */}
              <div
                {...mergeParts(api.value.getContentProps(), {
                  class: styles.content,
                  style: { '--radix-popover-content-transform-origin': 'var(--transform-origin)' },
                  hidden: undefined,
                  'aria-labelledby': undefined,
                  'aria-describedby': undefined,
                  'aria-label': say.value.chooseRange,
                  'data-member': 'date-range-picker',
                })}
                ref={panel.attach}
              >
                <DateRangePickerRangeCalendar
                  value={range.value}
                  minValue={props.minValue}
                  maxValue={props.maxValue}
                  isDateUnavailable={props.isDateUnavailable}
                  locale={language.value}
                  firstDayOfWeek={props.firstDayOfWeek}
                  disabled={props.disabled}
                  messages={say.value}
                  label={say.value.chooseRange}
                  onCommit={($event) => choose.value($event)}
                  onAnchorChange={($event) => (anchored.value = $event)}
                />
              </div>
            </div>
          ) : null}
          {scrimPresent() ? (
            <div
              class={sheet.scrim}
              data-state={api.value.open ? 'open' : 'closed'}
              ref={scrim.attach}
            />
          ) : null}
          {sheetPresent() ? (
            <div class={sheet.positioner}>
              <div
                {...mergeParts(api.value.getContentProps(), {
                  class: sheet.panel,
                  hidden: undefined,
                  'aria-labelledby': undefined,
                  'aria-describedby': undefined,
                  'aria-label': say.value.chooseRange,
                  'aria-modal': 'true',
                  'data-presentation': 'sheet',
                })}
                ref={sheetPanel.attach}
              >
                {/* sheetBody */}
                <div class={styles.sheetBody} data-member="date-range-picker">
                  <DateRangePickerRangeCalendar
                    value={range.value}
                    minValue={props.minValue}
                    maxValue={props.maxValue}
                    isDateUnavailable={props.isDateUnavailable}
                    locale={language.value}
                    firstDayOfWeek={props.firstDayOfWeek}
                    disabled={props.disabled}
                    messages={say.value}
                    label={say.value.chooseRange}
                    onCommit={($event) => choose.value($event)}
                    onAnchorChange={($event) => (anchored.value = $event)}
                  />
                </div>
              </div>
            </div>
          ) : null}
        </Portal>
      </>
    )
  })
}

DateRangePicker.controlKind = 'group'
